after.name:
analyzeArchitectureGraph.cycles.<callback:components
    .filter((component) => component.length > 1)
    .map((component) => {
      const cycle = architectureCycle(component, enforcedEdges, config.requireAcyclic === true);
      const members = new Set(component);
      const fileCycleMembers = fileComponents.find((files) =>
        files.every((file) => members.has(resolved.get(file) ?? '')),
      );
      return {
        ...cycle,
        origin: fileCycleMembers ? ('contains-file-cycle' as const) : ('grouping-only' as const),
        fileCycleMembers: fileCycleMembers ? [...fileCycleMembers].sort() : [],
      };
    })
    .sort:0>

responsibilityFindings.groups.<callback:independentFunctionGroups(fileFacts.functions)
      .map((group) => {
        const functions = group.filter((item) => item.exports.length && item.fn.tokenCount >= 60);
        const exports = new Set(functions.flatMap((item) => item.exports));
        return {
          functions,
          dependencies: [...new Set(group.flatMap((item) => item.dependencies))],
          consumers: consumers.filter((item) => item.target === file && (exports.has(item.name) || item.name === '*')),
        };
      })
      .filter:0>

